// src/app/add_asset/page.tsx
"use client";

import React, { useEffect, useMemo, useState } from "react";
import { useForm, Controller } from "react-hook-form";
import { s } from "./styles";
import {
    PlusCircle,
    Save,
    Wallet,
    LineChart,
    DollarSign,
    Globe,
    Landmark,
} from "lucide-react";

/* ---------- Typy formularza (luźne, dynamiczne) ---------- */
type FormValues = Record<string, any>;

/* ---------- Helper: rozpoznawanie typu aktywa (backend może zwracać PL lub EN) ---------- */
function isETF(value?: string) {
    return value === "ETF";
}
function isETC(value?: string) {
    return value === "ETC";
}
function isBOND(value?: string) {
    return value === "BOND" || value === "Obligacja" || value === "Obligacje";
}
function isEQUITY(value?: string) {
    return value === "EQUITY" || value === "Akcja" || value === "Akcje";
}
function isCRYPTO(value?: string) {
    return value === "CRYPTO" || value === "Kryptowaluta" || value === "Kryptowaluty";
}

/* ---------- Komponent ---------- */
export default function AddAssetPage() {
    const { register, handleSubmit, control, watch, reset, formState } = useForm<FormValues>({
        defaultValues: {
            ticker: "",
            name: "",
            asset_type: "",
            category1: "",
            category2: "",
            geo_region: "",
            geo_country: "",
            market_type: "",
            currency: "PLN",
            active: true,
            notes: "",
            // exchange-traded mixin defaults
            isin: "",
            issuer: "",
            ter: "",
            listing_venue: "",
            domicile: "",
            spread: "",
        },
    });

    const [meta, setMeta] = useState<Record<string, string[]>>({});
    const [metaLoading, setMetaLoading] = useState(true);
    const [metaError, setMetaError] = useState<string | null>(null);
    const [submitError, setSubmitError] = useState<string | null>(null);
    const [submitSuccess, setSubmitSuccess] = useState<string | null>(null);

    const assetType = watch("asset_type") as string | undefined;
    const isSubmitting = formState.isSubmitting;

    useEffect(() => {
        let mounted = true;
        setMetaLoading(true);
        setMetaError(null);

        fetch("/api/assets/meta")
            .then(async (res) => {
                if (!res.ok) {
                    const body = await res.text().catch(() => null);
                    throw new Error(body || `HTTP ${res.status}`);
                }
                return res.json();
            })
            .then((data) => {
                if (!mounted) return;
                setMeta(data);
            })
            .catch((err: any) => {
                if (!mounted) return;
                setMetaError(err?.message ?? "Błąd pobierania meta");
            })
            .finally(() => {
                if (!mounted) return;
                setMetaLoading(false);
            });

        return () => {
            mounted = false;
        };
    }, []);

    const onSubmit = async (data: FormValues) => {
        setSubmitError(null);
        setSubmitSuccess(null);

        // prosta walidacja klienta
        if (!data.asset_type) {
            setSubmitError("Wybierz typ instrumentu.");
            return;
        }
        if (!data.ticker || !data.ticker.trim()) {
            setSubmitError("Podaj ticker/symbol.");
            return;
        }
        if (!data.name || !data.name.trim()) {
            setSubmitError("Podaj nazwę instrumentu.");
            return;
        }

        // przygotowanie payloadu: usuń puste stringi i konwertuj liczby/datę
        const payload: Record<string, any> = {};
        Object.entries(data).forEach(([k, v]) => {
            if (v === "" || v === null || v === undefined) return;
            // checkboxy mogą być boolean
            if (typeof v === "string") {
                // daty typu YYYY-MM-DD zostaw jako są (backend Pydantic/SQLAlchemy przyjmie ISO date)
                payload[k] = v;
                return;
            }
            payload[k] = v;
        });

        // konwersje dodatkowe: jeśli są pola numeryczne w stringu -> Number
        ["ter", "spread", "nominal_value", "initial_rate", "margin", "early_redemption_penalty", "multiplier"].forEach(
            (k) => {
                if (payload[k] !== undefined && payload[k] !== null && payload[k] !== "") {
                    const n = Number(payload[k]);
                    if (!Number.isNaN(n)) payload[k] = n;
                }
            }
        );

        try {
            const res = await fetch("/api/assets", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(payload),
            });

            if (!res.ok) {
                const body = await res.json().catch(() => null);
                throw new Error(body?.detail ?? `Błąd serwera ${res.status}`);
            }

            setSubmitSuccess("Aktywo dodane pomyślnie.");
            reset();
        } catch (err: any) {
            setSubmitError(err?.message ?? "Nieznany błąd podczas zapisu.");
        }
    };

    const category1Options = meta.category1 ?? [];
    const category2Options = meta.category2 ?? [];
    const assetTypeOptions = meta.asset_type ?? [];
    const geoRegionOptions = meta.geo_region ?? [];
    const geoCountryOptions = meta.geo_country ?? [];
    const marketTypeOptions = meta.market_type ?? [];
    const distributionPolicyOptions = meta.distribution_policy ?? [];
    const replicationMethodOptions = meta.replication_method ?? [];
    const couponFrequencyOptions = meta.coupon_frequency ?? [];
    const interestHandlingOptions = meta.interest_handling ?? [];
    const retailBondBenchmarkOptions = meta.retail_bond_benchmark ?? [];

    return (
        <div className={s.container}>
            <div className="max-w-4xl mx-auto">
                <header className="mb-8 text-center md:text-left">
                    <h1 className="text-3xl font-extrabold flex items-center gap-3">
                        <PlusCircle size={34} className="text-blue-600" />
                        Dodaj aktywo
                    </h1>
                    <p className="text-gray-500 mt-1">Wypełnij dane instrumentu zgodnie z modelem bazy.</p>
                </header>

                <form className={s.card} onSubmit={handleSubmit(onSubmit)} noValidate>
                    {metaLoading && <div className="text-sm text-gray-500">Ładowanie wartości do list rozwijanych…</div>}
                    {metaError && <div className="text-sm text-red-600">Błąd pobierania meta: {metaError}</div>}

                    {/* podstawowe */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className={s.label}><Wallet size={14} /> Typ instrumentu</label>
                            <select {...register("asset_type")} className={s.select} disabled={metaLoading}>
                                <option value="">-- wybierz --</option>
                                {assetTypeOptions.map((v) => (
                                    <option key={v} value={v}>{v}</option>
                                ))}
                            </select>
                        </div>

                        <div>
                            <label className={s.label}><LineChart size={14} /> Ticker</label>
                            <input {...register("ticker")} className={s.input} placeholder="np. AAPL.US" />
                        </div>

                        <div>
                            <label className={s.label}>Nazwa</label>
                            <input {...register("name")} className={s.input} placeholder="Pełna nazwa instrumentu" />
                        </div>

                        <div>
                            <label className={s.label}><DollarSign size={14} /> Waluta</label>
                            <input {...register("currency")} className={s.input} placeholder="PLN" />
                        </div>
                    </div>

                    {/* geografia i rynek */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div>
                            <label className={s.label}><Globe size={14} /> Region</label>
                            <select {...register("geo_region")} className={s.select} disabled={metaLoading}>
                                <option value="">-- wybierz --</option>
                                {geoRegionOptions.map((v) => (
                                    <option key={v} value={v}>{v}</option>
                                ))}
                            </select>
                        </div>

                        <div>
                            <label className={s.label}>Kraj (opcjonalnie)</label>
                            <select {...register("geo_country")} className={s.select} disabled={metaLoading}>
                                <option value="">-- brak --</option>
                                {geoCountryOptions.map((v) => (
                                    <option key={v} value={v}>{v}</option>
                                ))}
                            </select>
                        </div>

                        <div>
                            <label className={s.label}>Typ rynku</label>
                            <select {...register("market_type")} className={s.select} disabled={metaLoading}>
                                <option value="">-- wybierz --</option>
                                {marketTypeOptions.map((v) => (
                                    <option key={v} value={v}>{v}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    {/* exchange-traded mixin (ETF/ETC/EQUITY/CRYPTO) */}
                    {(isETF(assetType) || isETC(assetType) || isEQUITY(assetType) || isCRYPTO(assetType)) && (
                        <div className={s.subCardEtf}>
                            <h3 className="font-bold mb-3">Dane notowane (opcjonalne)</h3>
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                                <input {...register("isin")} className={s.input} placeholder="ISIN" />
                                <input {...register("issuer")} className={s.input} placeholder="Emitent" />
                                <input {...register("listing_venue")} className={s.input} placeholder="Giełda / listing" />
                                <input {...register("domicile")} className={s.input} placeholder="Domicyl" />
                                <input {...register("ter")} className={s.input} placeholder="TER (%)" type="number" step="0.0001" />
                                <input {...register("spread")} className={s.input} placeholder="Spread" type="number" step="0.000001" />
                            </div>
                        </div>
                    )}

                    {/* ETF */}
                    {isETF(assetType) && (
                        <div className={s.subCardEtf}>
                            <h3 className="font-bold mb-3">Parametry ETF</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                <input {...register("benchmark")} className={s.input} placeholder="Benchmark" />
                                <select {...register("distribution_policy")} className={s.select} disabled={metaLoading}>
                                    <option value="">-- polityka dystrybucji --</option>
                                    {distributionPolicyOptions.map((v) => <option key={v} value={v}>{v}</option>)}
                                </select>
                                <select {...register("replication_method")} className={s.select} disabled={metaLoading}>
                                    <option value="">-- metoda replikacji --</option>
                                    {replicationMethodOptions.map((v) => <option key={v} value={v}>{v}</option>)}
                                </select>
                            </div>
                        </div>
                    )}

                    {/* ETC */}
                    {isETC(assetType) && (
                        <div className={s.subCardEtf}>
                            <h3 className="font-bold mb-3">Parametry ETC</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                <input {...register("multiplier")} className={s.input} placeholder="Multiplier" type="number" step="0.000001" />
                                <div className="flex items-center gap-3">
                                    <Controller
                                        control={control}
                                        name="physical_backing"
                                        render={({ field }) => (
                                            <input type="checkbox" {...field} checked={!!field.value} className="w-5 h-5" />
                                        )}
                                    />
                                    <label className="font-medium">Fizyczne pokrycie</label>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* BOND */}
                    {isBOND(assetType) && (
                        <div className={s.subCardBond}>
                            <h3 className="font-bold mb-3">Szczegóły obligacji</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                <input {...register("retail_series_type")} className={s.input} placeholder="Seria detaliczna" />
                                <input {...register("issue_date")} className={s.input} type="date" />
                                <input {...register("maturity_date")} className={s.input} type="date" />
                                <input {...register("nominal_value")} className={s.input} placeholder="Wartość nominalna" type="number" step="0.0001" />
                                <input {...register("initial_rate")} className={s.input} placeholder="Oprocentowanie początkowe (%)" type="number" step="0.0001" />
                                <select {...register("interest_handling")} className={s.select} disabled={metaLoading}>
                                    <option value="">-- sposób obsługi odsetek --</option>
                                    {interestHandlingOptions.map((v) => <option key={v} value={v}>{v}</option>)}
                                </select>
                                <select {...register("coupon_frequency")} className={s.select} disabled={metaLoading}>
                                    <option value="">-- częstotliwość kuponu --</option>
                                    {couponFrequencyOptions.map((v) => <option key={v} value={v}>{v}</option>)}
                                </select>
                                <input {...register("margin")} className={s.input} placeholder="Marża (%)" type="number" step="0.0001" />
                                <input {...register("early_redemption_penalty")} className={s.input} placeholder="Opłata przedterminowa" type="number" step="0.0001" />
                                <input {...register("rating")} className={s.input} placeholder="Rating" />
                                <div className="flex items-center gap-3">
                                    <Controller control={control} name="is_indexed" render={({ field }) => (
                                        <input type="checkbox" {...field} checked={!!field.value} className="w-5 h-5" />
                                    )} />
                                    <label className="font-medium">Indeksowana inflacją</label>
                                </div>
                                <div className="flex items-center gap-3">
                                    <Controller control={control} name="secured" render={({ field }) => (
                                        <input type="checkbox" {...field} checked={!!field.value} className="w-5 h-5" />
                                    )} />
                                    <label className="font-medium">Zabezpieczona</label>
                                </div>
                                <select {...register("benchmark")} className={s.select} disabled={metaLoading}>
                                    <option value="">-- benchmark obligacji (opcjonalnie) --</option>
                                    {retailBondBenchmarkOptions.map((v) => <option key={v} value={v}>{v}</option>)}
                                </select>
                            </div>
                        </div>
                    )}

                    {/* dodatkowe meta */}
                    <div>
                        <label className={s.label}>Kategoria główna</label>
                        <select {...register("category1")} className={s.select} disabled={metaLoading}>
                            <option value="">-- wybierz --</option>
                            {category1Options.map((v) => <option key={v} value={v}>{v}</option>)}
                        </select>
                    </div>

                    <div>
                        <label className={s.label}>Kategoria szczegółowa (opcjonalnie)</label>
                        <select {...register("category2")} className={s.select} disabled={metaLoading}>
                            <option value="">-- brak --</option>
                            {category2Options.map((v) => <option key={v} value={v}>{v}</option>)}
                        </select>
                    </div>

                    <div>
                        <label className={s.label}>Notatki</label>
                        <textarea {...register("notes")} className={s.input} rows={3} />
                    </div>

                    {submitError && <div className="text-sm text-red-600">{submitError}</div>}
                    {submitSuccess && <div className="text-sm text-green-600">{submitSuccess}</div>}

                    <div className="pt-3">
                        <button type="submit" className={s.button} disabled={isSubmitting || metaLoading}>
                            <Save size={18} />
                            {isSubmitting ? "Zapis..." : "Zapisz aktywo"}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}
